customEvals.script:
const charging = (game.user.character.flags.fq?.bladeCharging ? game.user.character.flags.fq.bladeCharging : 0) + Number(XXX);
if (charging <= 12) {
game.user.character.update({"flags.fq": { ...game.user.character.flags.fq, ...{ bladeCharging: charging } }});
}

ChatMessage.create({
                speaker: ChatMessage.getSpeaker({actor: game.user.character}),
                content: `<span font-style: italic'>
                    ${game.i18n.localize("FQCARDENGINE.CardMsgLoadScore")} ${charging > 12 ? game.user.character.flags.fq.bladeCharging : charging}</span>`
            });

const charging = (game.user.character.flags.fq?.bladeWhirlwind ? game.user.character.flags.fq.bladeWhirlwind : 0) + Number(XXX);
if (charging <= 8) {
game.user.character.update({"flags.fq": { ...game.user.character.flags.fq, ...{ bladeWhirlwind: charging } }});
}

ChatMessage.create({
                speaker: ChatMessage.getSpeaker({actor: game.user.character}),
                content: `<span font-style: italic'>
                    ${game.i18n.localize("FQCARDENGINE.CardMsgLoadScore")} ${charging > 12 ? game.user.character.flags.fq.bladeWhirlwind : charging}</span>`
            });
